import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { spawnSync } from 'node:child_process';

export async function gate({ referenceDir, submissionDir }) {
  const submissionPath = path.join(submissionDir, 'answer.mjs');
  if (!existsSync(submissionPath)) {
    return { accept: false, reason: 'answer.mjs not found in submissionDir' };
  }
  const pinnedPath = path.join(referenceDir, 'pinned-test-cases.txt');
  if (!existsSync(pinnedPath)) {
    return { accept: false, reason: 'pinned-test-cases.txt missing from referenceDir' };
  }
  // Touch the pinned file so we genuinely depend on it being present/readable.
  readFileSync(pinnedPath, 'utf8');

  const submissionUrl = pathToFileURL(path.resolve(submissionPath)).href;

  const fixedCases = [
    { name: 'empty array', input: [], expected: [] },
    { name: 'single element', input: [5], expected: [5] },
    { name: 'no duplicates', input: [1, 2, 3], expected: [1, 2, 3] },
    { name: 'all duplicates', input: [4, 4, 4, 4], expected: [4] },
    { name: 'duplicates at the start', input: [1, 1, 2, 3], expected: [1, 2, 3] },
    { name: 'duplicates at the end', input: [1, 2, 3, 3], expected: [1, 2, 3] },
    { name: 'negative numbers with duplicates', input: [-3, -3, -1, 0, 0, 2], expected: [-3, -1, 0, 2] },
  ];

  const results = [];
  for (const tc of fixedCases) {
    results.push({ name: tc.name, ...runIsolatedFixed({ referenceDir, submissionUrl, tc }) });
  }
  results.push({ name: 'randomized property check', ...runIsolatedRandom({ referenceDir, submissionUrl, trials: 20 }) });

  const allPass = results.every((r) => r.status === 'PASS');
  const summary = results.map((r) => r.name + ': ' + r.status + (r.detail ? ' (' + r.detail + ')' : '')).join('; ');

  return {
    accept: allPass,
    reason: (allPass ? 'all ' + results.length + ' pinned checks genuinely executed (isolated per-test child processes, file-verified completion) and passed: ' : 'rejected, not all pinned checks genuinely passed: ') + summary,
  };
}

function freshNonce() {
  return Math.random().toString(36).slice(2) + '-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2);
}

function runChildAndReadVerdict(referenceDir, harnessBody) {
  const nonce = freshNonce();
  const resultFile = path.join(referenceDir, 'result-' + nonce + '.json');
  const scriptFile = path.join(referenceDir, 'harness-' + nonce + '.mjs');

  // Default state the gate itself controls: unless the child genuinely runs its own
  // completion logic and overwrites this, we must treat the test as failed. Early
  // process termination (process.exit, crash, timeout, kill) leaves this untouched.
  writeFileSync(resultFile, JSON.stringify({ status: 'NOT_RUN' }));
  writeFileSync(scriptFile, harnessBody(resultFile));

  const res = spawnSync(process.execPath, [scriptFile], {
    timeout: 5000,
    encoding: 'utf8',
  });

  // Deliberately never consult res.stdout / res.stderr for the verdict: a submission
  // can print anything, including a forged success report. The only trusted signal
  // is the result file, and only insofar as it differs from the pre-seeded default.
  let raw;
  try {
    raw = readFileSync(resultFile, 'utf8');
  } catch (e) {
    return { status: 'FAIL', detail: 'result file unreadable after run' };
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    return { status: 'FAIL', detail: 'result file corrupt' };
  }

  if (res.error) {
    return { status: 'FAIL', detail: 'subprocess error: ' + String(res.error.message || res.error) };
  }
  if (res.signal) {
    return { status: 'FAIL', detail: 'subprocess killed by signal ' + res.signal + ' (likely timeout/hang)' };
  }
  if (parsed.status === 'NOT_RUN') {
    return { status: 'FAIL', detail: 'harness never reported completion (process exited early, before assertion ran)' };
  }
  if (parsed.status === 'PASS') {
    return { status: 'PASS' };
  }
  return { status: 'FAIL', detail: parsed.detail || 'assertion did not hold' };
}

function runIsolatedFixed({ referenceDir, submissionUrl, tc }) {
  return runChildAndReadVerdict(referenceDir, (resultFile) => {
    const resultFileLit = JSON.stringify(resultFile);
    const inputLit = JSON.stringify(tc.input);
    const expectedLit = JSON.stringify(tc.expected);
    const subUrlLit = JSON.stringify(submissionUrl);
    return [
      "import assert from 'node:assert/strict';",
      "import { writeFileSync } from 'node:fs';",
      'let mod;',
      'try {',
      '  mod = await import(' + subUrlLit + ');',
      '  const dedupeSorted = mod.dedupeSorted;',
      '  const input = ' + inputLit + ';',
      '  const expected = ' + expectedLit + ';',
      '  const actual = dedupeSorted(input);',
      '  assert.deepStrictEqual(actual, expected);',
      '  writeFileSync(' + resultFileLit + ', JSON.stringify({ status: "PASS" }));',
      '} catch (e) {',
      '  writeFileSync(' + resultFileLit + ', JSON.stringify({ status: "FAIL", detail: String((e && e.message) || e) }));',
      '}',
    ].join('\n');
  });
}

function runIsolatedRandom({ referenceDir, submissionUrl, trials }) {
  return runChildAndReadVerdict(referenceDir, (resultFile) => {
    const resultFileLit = JSON.stringify(resultFile);
    const subUrlLit = JSON.stringify(submissionUrl);
    return [
      "import assert from 'node:assert/strict';",
      "import { writeFileSync } from 'node:fs';",
      'try {',
      '  const mod = await import(' + subUrlLit + ');',
      '  const dedupeSorted = mod.dedupeSorted;',
      '  for (let trial = 0; trial < ' + trials + '; trial++) {',
      '    const len = 1 + Math.floor(Math.random() * 10);',
      '    const arr = Array.from({ length: len }, () => Math.floor(Math.random() * 5) - 2).sort((a, b) => a - b);',
      '    const expected = [...new Set(arr)];',
      '    const actual = dedupeSorted(arr);',
      '    assert.deepStrictEqual(actual, expected);',
      '  }',
      '  writeFileSync(' + resultFileLit + ', JSON.stringify({ status: "PASS" }));',
      '} catch (e) {',
      '  writeFileSync(' + resultFileLit + ', JSON.stringify({ status: "FAIL", detail: String((e && e.message) || e) }));',
      '}',
    ].join('\n');
  });
}

